-- Official answer key: https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_ans.pdf
INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h29h-2017-q41','ITサービスマネジメント・OLA','standard','single_choice','【2017年度 平成29年春期 午前 問41】ITサービスマネジメントにおける運用レベル合意書（OLA）の説明はどれか。','[{"id":"a","text":"サービス提供者と供給者との間で取り交わし，サービス及びサービス目標を定義する合意文書"},{"id":"b","text":"サービス提供者と顧客との間で取り交わし，サービス及びサービス目標を定義する合意文書"},{"id":"c","text":"サービス提供者と内部グループとの間で取り交わし，サービス及びサービス目標を定義する合意文書"},{"id":"d","text":"顧客に提示するため，提供する全サービスの種類や構成を定義した文書"}]','"c"','正解はウ。OLAはサービス提供者と組織内部のグループとの間で結ぶ運用上の合意であり，外部顧客とのSLAとは異なる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q42','ITサービスマネジメント・問題管理','standard','single_choice','【2017年度 平成29年春期 午前 問42】ITサービスマネジメントにおける問題管理プロセスの目的はどれか。','[{"id":"a","text":"インシデントの解決を，合意したサービス目標及び時間枠内に達成することを確実にする。"},{"id":"b","text":"インシデントの根本原因を特定し，恒久的な解決策を提案するとともに，インシデントの発生を事前に防止する。"},{"id":"c","text":"合意した目標の中で，サービス継続及び可用性のコミットメントを果たすことを確実にする。"},{"id":"d","text":"全ての変更を制御された方法で評価，承認，実施，レビューすることを確実にする。"}]','"b"','正解はイ。問題管理はインシデントの根本原因を調査し，恒久対策や再発防止につなげる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q44','システム構成・ホットスタンバイ','standard','single_choice','【2017年度 平成29年春期 午前 問44】ホットスタンバイ方式を採用したシステム構成の特徴はどれか。','[{"id":"a","text":"現用系が故障すると，待機系に手動で切り替える。待機系は平常時にバッチジョブにも利用できる。"},{"id":"b","text":"現用系が故障すると，動作状態にある待機系に自動で迅速に切り替え，利用者に故障を感じさせにくい。"},{"id":"c","text":"システムを三重化して並列運転し，処理結果の多数決を取る。"},{"id":"d","text":"複数の現用系の故障に備えて予備機を一台用意し，故障時に起動してネットワーク等を切り替える。"}]','"b"','正解はイ。ホットスタンバイでは待機系も稼働状態にあり，現用系の障害時に迅速な切替えが可能である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q45','データ分析・データマイニング','standard','single_choice','【2017年度 平成29年春期 午前 問45】ビッグデータの活用例として，大量のデータから統計学的手法などを用いて新たな知識（傾向やパターン）を見つけ出すプロセスはどれか。','[{"id":"a","text":"データウェアハウス"},{"id":"b","text":"データディクショナリ"},{"id":"c","text":"データマイニング"},{"id":"d","text":"メタデータ"}]','"c"','正解はウ。データマイニングは大量のデータを分析し，傾向やパターンなどの有用な知識を発見する手法である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q46','HTTP・ステータスコード','standard','single_choice','【2017年度 平成29年春期 午前 問46】PCからWebサーバにHTTPでアクセスしたところ，ステータスコード404，説明文字列「Not Found」のエラーになった。このエラーの説明として適切なものはどれか。','[{"id":"a","text":"Webサーバ内に，URLで指定したページが見つからなかった。"},{"id":"b","text":"Webサーバのホスト名をDNSで検索したが，見つからなかった。"},{"id":"c","text":"WebサーバへのIPパケットの経路が見つからず，HTTPリクエストがタイムアウトになった。"},{"id":"d","text":"Webサーバへのログイン時に指定した利用者IDが見つからず，ログインが拒否された。"}]','"a"','正解はア。HTTP 404は要求されたリソースが見つからないことを表し，DNS解決失敗や通信タイムアウトとは異なる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q47','経営戦略・IT戦略','standard','single_choice','【2017年度 平成29年春期 午前 問47】情報戦略の立案時に，必ず整合性を取るべきものはどれか。','[{"id":"a","text":"新しく登場した情報技術"},{"id":"b","text":"基幹システムの改修計画"},{"id":"c","text":"情報システム部門の年度計画"},{"id":"d","text":"中長期の経営計画"}]','"d"','正解はエ。情報戦略は企業の中長期的な経営方針・経営計画と整合している必要がある。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q48','業務改革・BPR','standard','single_choice','【2017年度 平成29年春期 午前 問48】システム企画段階において業務プロセスを抜本的に再設計する際の留意点はどれか。','[{"id":"a","text":"新たな視点から高い目標を設定し，将来的に必要となる最上位の業務機能と業務組織のモデルを検討する。"},{"id":"b","text":"ビジネスモデルの将来像にはこだわらず，現場レベルのニーズや課題への対応を重視する。"},{"id":"c","text":"経営者や管理者の非定型業務ではなく，一般社員による定型業務だけを対象とする。"},{"id":"d","text":"現行の組織や業務手続を前提として，その範囲内で業務プロセスを再設計する。"}]','"a"','正解はア。BPRでは既存手順の小さな改善にとどまらず，将来像から業務プロセスを抜本的に再設計する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q49','システム要件・非機能要件','standard','single_choice','【2017年度 平成29年春期 午前 問49】受注管理システムにおける要件のうち，非機能要件に該当するものはどれか。','[{"id":"a","text":"注文受付時に与信残額を計算し，結果がマイナスなら入力画面に警告を表示する。"},{"id":"b","text":"稼働率を所定の水準に維持するため，障害発生時は半日以内に回復できる。"},{"id":"c","text":"在庫切れの商品であることが分かるよう，担当者に警告メッセージを表示する。"},{"id":"d","text":"受注担当者が注文情報を入力し，営業管理者が承認入力した注文だけを処理する。"}]','"b"','正解はイ。障害からの回復時間や稼働率は品質・可用性に関する非機能要件であり，業務処理の具体的機能とは異なる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q50','事業継続計画・BCP','standard','single_choice','【2017年度 平成29年春期 午前 問50】企業活動におけるBCPを説明したものはどれか。','[{"id":"a","text":"企業が社会に与える影響に責任をもち，ステークホルダへの説明責任を果たす取組"},{"id":"b","text":"形式知だけでなく暗黙知も共有・活用し，新たな知識を創造しながら経営を実践する手法"},{"id":"c","text":"災害やシステム障害などの予期せぬ事態でも重要な業務を継続できるよう，事前に策定する行動計画"},{"id":"d","text":"組織のあらゆるリスクを統合的・包括的・戦略的に把握，評価，最適化する手法"}]','"c"','正解はウ。BCP（事業継続計画）は災害や障害が起きても重要業務を継続・早期復旧するための事前計画である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja');
